var calc_output = [];

var anemia = parseFloat(anemia) || 0;
var syncope = parseFloat(syncope) || 0;
var renaldys = parseFloat(renaldys) || 0;

var score = anemia + syncope + renaldys;

var risk;

if (score === 0) {
    risk = 'Low';
} else if (score >= 1 && score <= 2.5) {
    risk = 'Intermediate';
} else {
    risk = 'High';
}

calc_output.push({
    name: 'mini',
    value: score,
    value_text: 'points',
    message: risk + ' risk of early major bleeding'
});
calc_output.push({
    name: '10602_PE-SARD_result',
    value: score,
    value_text: 'points',
    message: 'PE-SARD Score'
});
calc_output.push({
    name: '10602_PE-SARD_interpretation',
    value: risk,
    value_text: 'risk',
    message: 'Risk of early major bleeding'
});
